  const turbulence = Math.sin(sx*0.08+Math.sin(sy*0.06+t)*3+t*0.7)*Math.cos(sy*0.07+Math.cos(sx*0.05-t)*2-t*0.5)*0.3;
  const cross = aS*iS*0.6 + cS*aS*0.4;
  const reaction = Math.tanh((aS - iS*0.6 + bg*0.25 + spiral + turbulence + cross*0.3)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const fiber = Math.sin(Math.sin(sx*0.08+t*0.3)*6+sy*0.12)*Math.cos(Math.cos(sy*0.06-t*0.4)*5+sx*0.1)*0.15;
  const blend = reaction*0.6 + cell*0.2 + fiber*0.2;
  const v = blend*0.5+0.5;
  const vignette = 1.0 - dist*0.0012;
  const glow = Math.max(0, Math.abs(reaction)-0.6)*2.5;
  const lum = (0.8+Math.sin(reaction*Math.PI)*0.2)*vignette + glow*0.15;
  const edge = Math.abs(reaction)>0.65?1.2:1.0;
  const pal = [[6,12,52],[12,45,88],[18,85,120],[30,140,135],[120,175,120],[210,190,60],[225,130,55],[195,65,55],[120,30,60],[50,15,55],[6,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge)|0
  ];
}
